$lang['sa_map_info'] = 'When a <strong>Payment Request from a PO</strong> is approved, the system creates an AP Invoice + payable journal: <strong>Dr the account below</strong> (Inventory / Expense / Asset) + Dr Input VAT, <strong>Cr Accounts Payable</strong>. The account is looked up in order: <strong>per-item exception</strong> → account in Asset Master (assets only) → <strong>per category</strong> → <strong>default per item type</strong>. If none is found, the Payment Request approval is rejected until the account is set here. The requester never has to choose an account.';
